// The unread dot is the read toggle: it already occupies the left gutter, so the action costs no width.
function dotButton(attr,id,read,title){return `<button type="button" class="dotbtn ${read?'done':''}" ${attr}="${esc(id)}" aria-label="${dotLabel(read)}: ${esc(title)}" aria-description="Estado: ${read?'leído':'no leído'}" title="${dotLabel(read)}">${dotInner(read)}</button>`}
