function specialCard(x){const read=specialRead(x);return `<article id="special-${esc(x.id)}" tabindex="-1" class="signal special big-feature ${x.kind} ${read?'read':''}" data-special="${esc(x.id)}"><div class="big-eyebrow">${dotButton('data-special-read',x.id,read,x.title)}<span>${specialLabel(x)}</span></div><h2><button class="title-open" data-special-open="${esc(x.id)}">${esc(x.title)}</button></h2>${x.summary?`<p class="big-summary">${esc(x.summary)}</p>`:''}<div class="card-meta"><span class="meta-text">${esc(x.source)}${x.date?` · ${fmtBriefDate(x.date)}`:''}</span><span class="item-actions">${miniShare(`special-${x.id}`,x.title)}<button type="button" class="big-cta" data-special-open="${esc(x.id)}">${x.kind==='global'?'Explorar Global':'Ver análisis'} →</button></span></div></article>`}
