function draw(){const hashTarget=sharedHashTarget();if(hashTarget.startsWith('sig-')&&hashTarget!==revealedHash&&!document.getElementById(hashTarget)){const signal=allSignals.find(x=>idFor(x)===hashTarget.slice(4));if(signal){activeType='Todos';activeScope='Todos';if(!inPeriod(signal))periodMode='90';if(laneMode!=='t'&&(laneMode==='p')===isRead(signal))laneMode='t';const period=document.getElementById('period');if(period)period.value=periodMode;persistFilters();renderFilters()}}if(hashTarget.startsWith('special-')&&hashTarget!==revealedHash&&laneMode==='p'){const x=specials().find(y=>y.id===hashTarget.slice(8));if(x&&specialRead(x)){laneMode='l';persistFilters()}}const v=visible(),shown=laneSignals(v);updateMetrics();brief();const groups=inboxGroups(shown);const unmeasured=periodMode==='last'&&previousVisit&&allSignals.some(s=>!s.ingestion_mode||!s.detected_at);const empty=laneMode==='p'?(unmeasured?'No se puede verificar qué cambió desde tu última visita: parte del histórico no tiene fecha de detección. Usa 14 días para revisar las señales.':'Estás al día con las señales de este período.'):laneMode==='l'?'Aún no hay señales leídas en este período.':'No hay señales en este período.';const readSpecials=laneMode==='p'?[]:specials().filter(specialRead);if(readSpecials.length)groups.unshift(['Ediciones de la semana',readSpecials]);const host=document.getElementById('local');host.innerHTML=`<div class="inbox">${groups.length?groups.map(([n,xs])=>`<section class="inbox-group" aria-label="${n}"><h3 class="group-head">${n}</h3>${xs.map(x=>x.kind?specialRow(x):card(x)).join('')}</section>`).join(''):`<p class="inbox-empty">${empty}</p>`}</div>`;host.querySelectorAll('[data-read]').forEach(b=>b.onclick=()=>{const s=v.find(x=>idFor(x)===b.dataset.read);if(s)toggleRead(s)});host.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>{const s=v.find(x=>idFor(x)===b.dataset.detail);if(s)openDetail(s)});host.querySelectorAll('[data-share]').forEach(b=>b.onclick=()=>shareCard(b));host.querySelectorAll('[data-special-open]').forEach(b=>b.onclick=()=>{const x=specials().find(y=>y.id===b.dataset.specialOpen);if(x)openSpecial(x)});revealSharedHash()}
function chips(id,values,current,setter){document.getElementById(id).innerHTML=values.map(v=>`<button class="chip ${v===current?'active':''}" data-v="${esc(v)}">${esc(v)}</button>`).join('');document.querySelectorAll(`#${id} .chip`).forEach(b=>b.onclick=()=>{setter(b.dataset.v);persistFilters();renderFilters();draw()})}
function renderFilters(){const types=['Todos',...['Normativa','Legal','Noticias','Datos','Fiscalización'].filter(x=>allSignals.some(s=>typeTags(s).includes(x)))];const scopes=['Todos',...new Set(allSignals.flatMap(scopeTags))];chips('typeFilters',types,activeType,v=>activeType=v);chips('scopeFilters',scopes,activeScope,v=>activeScope=v)}
function insightList(label,value){const items=Array.isArray(value)?value:value?[value]:[];return items.length?`<h3>${esc(label)}</h3><ul>${items.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}
function renderWeeklyDetail(w){document.getElementById('weeklyInsightBody').innerHTML=`<h2 id="weeklyInsightTitle">${esc(w.insight_title||w.title)}</h2><p class="meta-line">${esc(w.source_name)} · ${fmtDate(w.event_date)}</p><p>${esc(w.summary)}</p>${insightList('Cifras y alcance',w.key_figures)}${insightList('Actores',w.actors)}${insightList('Lectura Alicanto:',w.insight_reading)}${insightList('Decisiones que cambia',w.decision_use)}${insightList('Qué observar',w.what_to_watch)}${insightList('Límites de la evidencia',w.uncertainties)}<h3>Fuentes</h3><ul>${arr(w.sources).filter(x=>/^https:\/\//.test(x.url||'')).map((x,i)=>`<li><a href="${esc(x.url)}" target="_blank" rel="noopener">${i===0?'Revisar fuente original · ':''}${esc(x.label)}</a> · ${esc(x.role)}</li>`).join('')}</ul>`}
async function renderFreeValue(d){await AlicantoRead.ready;freeValue=d||{};const weekly=currentWeekly();document.getElementById('valueHighlights').hidden=true;document.getElementById('weeklyInsightBody').innerHTML='';if(weekly){renderWeeklyDetail(weekly);}if(allSignals.length)draw()}
if(typeof document!=='undefined'){document.getElementById('period').disabled=true;document.getElementById('sort').disabled=true;}
if(typeof window!=='undefined')window.setInterval(()=>{if(freeValue.weekly_insight&&!currentWeekly()){const dialog=document.getElementById('weeklyInsightDialog');if(dialog?.open)dialog.close();if(allSignals.length)draw()}},60000);

const freeValueLoad=typeof fetch==='function'?fetch('data/free_value.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw new Error('free value');return r.json()}).then(renderFreeValue).catch(()=>{}):Promise.resolve();
fetch('data/radar_today.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw new Error('snapshot');return r.json()}).then(async d=>{await AlicantoRead.ready;await freeValueLoad;const updateLabel=fmtUpdated(d.generated_at);allSignals=d.signals||[];await migrateReads();await migrateWeekly(currentWeekly());const types=['Todos',...['Normativa','Legal','Noticias','Datos','Fiscalización'].filter(x=>allSignals.some(s=>typeTags(s).includes(x)))],scopes=['Todos',...new Set(allSignals.flatMap(scopeTags))];if(!types.includes(activeType))activeType='Todos';if(!scopes.includes(activeScope))activeScope='Todos';if(!['last','7','14','30','60','90'].includes(periodMode))periodMode='30';if(!['personalized','date'].includes(sortMode))sortMode='date';document.getElementById('sort').value=sortMode;const period=document.getElementById('period');period.value=periodMode;renderFilters();draw();document.getElementById('meta').textContent=updateLabel;persistFilters();period.onchange=e=>{periodMode=e.target.value;persistFilters();draw()};document.getElementById('sort').onchange=e=>{sortMode=e.target.value;persistFilters();draw()};const reset=document.getElementById('resetFilters');if(reset)reset.onclick=()=>{activeType='Todos';activeScope='Todos';sortMode='date';periodMode='30';period.value=periodMode;document.getElementById('sort').value=sortMode;persistFilters();renderFilters();draw()};period.disabled=false;document.getElementById('sort').disabled=false;saveLocal('alicanto_last_visit',new Date().toISOString())}).catch(()=>document.getElementById('local').innerHTML='<div>No se pudo cargar Alicanto.</div>');

